"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useState } from "react";
import { AlertTriangle, ArrowRight, BarChart3, BookOpen, CalendarRange, CheckCircle2, CircleDollarSign, FileCheck2, FileSpreadsheet, FileText, Landmark, Plus, RefreshCw, Settings2, UploadCloud, Workflow } from "lucide-react";
import { Badge, Button, Drawer, Field, Input, Modal, Select, useToast } from "@/app/components/ui/primitives";
import { DataState, DataToolbar, PageHeading, Table } from "@/app/components/ui/data";
import { getSupabaseClient } from "@/app/lib/supabase";
import { accountingReportColumnLabel as reportColumnLabel, accountingReportDescription as reportDescription, accountingReportKeys, accountingReportLabel as reportLabel, isAccountingAmountKey as isAmountKey } from "@/app/lib/accounting-report";

export type AccountingView = "summary" | "accounts" | "periods" | "reports" | "journals" | "events" | "opening" | "settings";
type Account = { id: string; code: string; name: string; account_type: string; normal_balance: string; parent_id: string | null; level: number; accepts_posting: boolean; is_active: boolean; updated_at:string };
type Config = { id: string; version: number; status: string; base_currency: string; cutoff_date: string; catalog_structure: { format?: string }; tax_treatment: Record<string, string>; responsibilities: Record<string, string>; change_reason: string; approved_at: string | null; updated_at: string };
type Period = { id: string; period_code: string; starts_on: string; ends_on: string; status: string };
type Line = { id: string; line_number: number; account_id: string; description: string | null; debit: number; credit: number; external_account_code: string | null };
type Journal = { id: string; entry_number: number; entry_date: string; description: string; source_type: string; status: string; immutable: boolean; posted_at: string | null; accounting_journal_lines: Line[] };
type Batch = { id: string; import_type: "chart_of_accounts" | "trial_balance"; cutoff_date: string | null; currency_code: string | null; catalog_structure: { format?: string; segments?: number[] }; detection_evidence: Record<string, { status?: string; value?: unknown; evidence?: Array<{ sheet: string; cell: string; raw: string }> }>; metadata_issues: Array<{ field: string; status: string }>; original_name: string; status: string; row_count: number; error_count: number; warning_count: number; promoted_entry_id: string | null };
type Exception = { id: string; batch_id: string; exception_code: string; severity: string; message: string; accounting_import_rows?: { external_account_code?: string } | Array<{ external_account_code?: string }> | null };
type Comparison = { batch_id: string; control_key: string; ledger_amount: number; auxiliary_amount: number; difference: number; detail: Record<string, unknown> };
type Control = { config_version_id: string; control_key: string; account_id: string };
type Responsible = { id: string; name: string };
type EventRuleSet = { id: string; version: number; status: "draft" | "approved" | "superseded"; cost_method: string; reason: string; approved_at: string | null };
type EventRoleAccount = { rule_set_id: string; account_role: string; account_id: string };
type AccountingEvent = { id: string; event_type: string; source_entity_type: string; source_entity_id: string; accounting_date: string; status: "pending" | "posted"; journal_entry_id: string | null; original_event_id: string | null; accounting_journal_entries?: { entry_number: number } | Array<{ entry_number: number }> | null };
type ManualAdjustment = { id:string;adjustment_type:string;entry_date:string;description:string;reason:string;status:"submitted"|"approved"|"rejected"|"reversed";requested_by:string;decided_by:string|null;journal_entry_id:string|null;reversal_entry_id:string|null };
type ExpenseCategory = { id:string;category_id:string;version:number;code:string;display_name:string;account_id:string;status:"active"|"inactive";valid_from:string;valid_to:string|null;change_reason:string;created_at:string };
type ClassificationWork = { items:Array<{preserved_text:string;line_count:number;invoice_count:number;oldest_date:string}>;pagination:{page:number;page_size:number;total:number} };
type Location = { id:string;name:string;external_code:string };
type CloseCheck = { code:string;blocking:boolean;expected:number|null;actual:number|null;difference:number|null;passed:boolean;detail?:Record<string,unknown> };
type CloseRun = { id:string;period_id:string;status:"prepared"|"approved"|"closed"|"reopened";snapshot:{checks?:CloseCheck[]};snapshot_sha256:string;prepared_by:string;prepared_at:string;approval_reason:string|null;approved_by:string|null;approved_at:string|null;closed_by:string|null;closed_at:string|null;reopened_by:string|null;reopen_reason:string|null;reopened_at:string|null };
type ReportResult = { report_type:string;starts_on:string;ends_on:string;page:number;page_size:number;total:number;totals:Record<string,number>;balanced:boolean|null;rows:Array<Record<string,unknown>>;scope?:string;location_label?:string|null };
type Payload = { accounts: Account[]; configs: Config[]; controls: Control[]; periods: Period[]; journals: Journal[]; batches: Batch[]; exceptions: Exception[]; comparisons: Comparison[]; responsibles: Responsible[]; eventRuleSets: EventRuleSet[]; eventRoleAccounts: EventRoleAccount[]; events: AccountingEvent[]; manualAdjustments:ManualAdjustment[];expenseCategories:ExpenseCategory[];classificationWork:ClassificationWork;locations:Location[];closeRuns:CloseRun[] };

const empty: Payload = { accounts: [], configs: [], controls: [], periods: [], journals: [], batches: [], exceptions: [], comparisons: [], responsibles: [], eventRuleSets: [], eventRoleAccounts: [], events: [], manualAdjustments:[],expenseCategories:[],classificationWork:{items:[],pagination:{page:1,page_size:100,total:0}},locations:[],closeRuns:[] };
const controlLabels: Record<string, string> = { accounts_receivable: "Cuentas por cobrar", accounts_payable: "Cuentas por pagar", inventory: "Inventario", cash: "Caja", banks: "Bancos", vat_pending: "IVA pendiente", vat_collected: "IVA cobrado", vat_paid: "IVA pagado", withholdings: "Retenciones" };
const controlKeys = Object.keys(controlLabels);
const eventRoleLabels: Record<string,string> = { sales_revenue:"Ventas",sales_discounts:"Descuentos sobre venta",cost_of_goods_sold:"Costo de ventas",goods_received_not_invoiced:"Mercancía recibida no facturada",purchase_variance:"Variación de compra",supplier_expense:"Gastos y servicios",cash_opening_offset:"Fondo de apertura",cash_close_offset:"Retiro al cierre",cash_movement_offset:"Contrapartida de caja",cash_over_short:"Sobrantes y faltantes",supplier_credit_note_offset:"Notas de crédito",inventory_adjustment:"Ajustes de inventario" };
const eventRoleKeys=Object.keys(eventRoleLabels);
const titles: Record<AccountingView, [string, string, string]> = {
  summary: ["Contabilidad", "Resumen contable", "Avance de la apertura, periodos y pólizas de la empresa."],
  accounts: ["Catálogo contable", "Catálogo de cuentas", "Crea y administra cuentas canónicas; la importación acelera catálogos extensos."],
  periods: ["Control contable", "Periodos", "Administra apertura, cierre y reapertura con trazabilidad."],
  reports: ["Información financiera", "Estados financieros", "Consulta cifras reproducibles directamente desde el libro contable."],
  journals: ["Libro diario", "Pólizas", "Consulta pólizas contabilizadas y sus partidas de doble entrada."],
  events: ["Automatización contable", "Eventos contables", "Define una vez las reglas y revisa la trazabilidad automática de tus operaciones."],
  opening: ["Inicio contable", "Apertura y conciliación", "Revisa los archivos detectados y promueve una apertura controlada."],
  settings: ["Finanzas", "Configuración contable", "Configura una empresa desde cero o confirma los datos detectados en archivos contables."],
};

export function AccountingModule({ companyId, permissions, view }: { companyId: string; permissions: string[]; view: AccountingView }) {
  const { toast } = useToast();
  const [data, setData] = useState<Payload>(empty);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const request = useCallback(async (init?: RequestInit) => {
    const session = (await getSupabaseClient().auth.getSession()).data.session;
    if (!session) throw new Error("Sesión no válida.");
    const response = await fetch(`/api/imports/accounting${init ? "" : `?companyId=${encodeURIComponent(companyId)}`}`, { ...init, headers: { Authorization: `Bearer ${session.access_token}`, ...(init?.headers ?? {}) }, cache: "no-store" });
    const result = await response.json();
    if (!response.ok) throw new Error(result.message ?? "No se pudo completar la operación.");
    return result;
  }, [companyId]);
  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try { setData({ ...empty, ...await request() }); }
    catch (loadError) { setError(loadError instanceof Error ? loadError.message : "No se pudo cargar Contabilidad."); }
    finally { setLoading(false); }
  }, [request]);
  useEffect(() => { void Promise.resolve().then(load); }, [load]);
  async function run(body: Record<string, unknown>, success: string) {
    setBusy(true);
    try { await request({ method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }); await load(); toast({ title: success, tone: "success" }); }
    catch (runError) { toast({ title: "No se pudo completar", description: runError instanceof Error ? runError.message : "Intenta nuevamente.", tone: "error" }); }
    finally { setBusy(false); }
  }
  const [eyebrow, title, description] = titles[view];
  const approved = data.configs.find((item) => item.status === "approved");
  const draft = data.configs.find((item) => item.status === "draft");
  const hasBase = Boolean(draft || approved); const hasCatalog = data.accounts.length > 0; const hasPeriod = data.periods.some((item) => item.status === "open");
  const locked = view === "accounts" ? false : view === "periods" || view === "reports" ? !(approved && hasCatalog) : view === "journals" ? !(approved && hasPeriod) : view === "events" ? !(approved && hasCatalog) : view === "opening" ? !hasBase : false;
  return <div className="content-frame accounting-module">
    <PageHeading eyebrow={eyebrow} title={title} description={description} action={<Button variant="secondary" loading={loading} onClick={() => void load()}><RefreshCw size={15} /> Actualizar</Button>} />
    <DataState loading={loading} error={error} hasData={1} empty="" errorAction={<Button size="sm" onClick={() => void load()}>Reintentar</Button>}>
      {locked && <LockedStep view={view} />}
      {!locked && view === "summary" && <AccountingSummary data={data} approved={approved} draft={draft} />}
      {!locked && view === "accounts" && <AccountsView companyId={companyId} accounts={data.accounts} batches={data.batches} categories={data.expenseCategories} classificationWork={data.classificationWork} disabled={busy} canConfigure={permissions.includes("configure_accounting")} onRun={run} />}
      {!locked && view === "periods" && <PeriodsView periods={data.periods} closeRuns={data.closeRuns} responsibles={data.responsibles} companyId={companyId} cutoff={approved?.cutoff_date} disabled={busy} permissions={permissions} onRun={run} />}
      {!locked && view === "reports" && <ReportsView companyId={companyId} accounts={data.accounts} periods={data.periods} locations={data.locations} />}
      {!locked && view === "journals" && <JournalsView companyId={companyId} journals={data.journals} accounts={data.accounts} adjustments={data.manualAdjustments} permissions={permissions} disabled={busy} onRun={run} />}
      {!locked && view === "events" && <EventsView key={`${companyId}:${data.accounts.length}`} companyId={companyId} accounts={data.accounts} ruleSets={data.eventRuleSets} roleAccounts={data.eventRoleAccounts} events={data.events} disabled={busy} canConfigure={permissions.includes("configure_accounting_events")} canReprocess={permissions.includes("reprocess_accounting_events")} onRun={run} />}
      {!locked && view === "opening" && <OpeningView data={data} approved={approved} hasPeriod={hasPeriod} disabled={busy} onRun={run} />}
      {view === "settings" && <SettingsView key={`${data.batches[0]?.id ?? "none"}:${draft?.id ?? approved?.id ?? "none"}:${data.accounts.length}`} companyId={companyId} data={data} accounts={data.accounts} approved={approved} draft={draft} controls={data.controls} disabled={busy} canConfigure={permissions.includes("configure_accounting")} onRun={run} />}
    </DataState>
  </div>;
}

function LockedStep({ view }: { view: AccountingView }) {
  const message = view === "accounts" ? "Primero sube un archivo contable y confirma la detección automática." : view === "periods" || view === "reports" || view === "events" ? "Primero promueve el catálogo y aprueba sus cuentas de control." : view === "journals" ? "Primero aprueba la configuración y abre el periodo de la fecha detectada." : "Primero confirma en Configuración los datos detectados del archivo.";
  return <section className="accounting-readiness"><span className="accounting-readiness__icon"><AlertTriangle size={22} /></span><div><strong>Paso todavía bloqueado</strong><p>{message}</p></div><Link className="ui-button ui-button--secondary ui-button--md" href={view === "accounts" || view === "opening" ? "/satrapy/configuracion/contabilidad" : "/satrapy/contabilidad/catalogo"}>Continuar en el paso anterior</Link></section>;
}

function AccountingSummary({ data, approved, draft }: { data: Payload; approved?: Config; draft?: Config }) {
  const open = data.periods.filter((item) => item.status === "open").length;
  const posted = data.journals.filter((item) => item.status === "posted").length;
  const opening = data.batches.find((item) => item.import_type === "trial_balance" && item.status === "promoted");
  const steps = [
    { label: "Origen", complete: data.batches.length > 0 || Boolean(draft||approved), description: data.batches.length ? `${data.batches.length} archivo${data.batches.length === 1 ? "" : "s"} contable${data.batches.length === 1 ? "" : "s"} detectado${data.batches.length === 1 ? "" : "s"}` : draft||approved ? "Inicio manual sin archivos" : "Elige captura manual o importación", href: "/satrapy/configuracion/contabilidad" },
    { label: "Configuración", complete: Boolean(draft || approved), description: approved ? `Versión ${approved.version} aprobada` : draft ? `Versión ${draft.version} confirmada` : "Revisa la detección automática", href: "/satrapy/configuracion/contabilidad" },
    { label: "Catálogo", complete: data.accounts.length > 0, description: data.accounts.length ? `${data.accounts.length.toLocaleString("es-MX")} cuentas disponibles` : "Crea cuentas o importa el catálogo", href: "/satrapy/contabilidad/catalogo" },
    { label: "Controles", complete: Boolean(approved), description: approved ? "Nueve auxiliares vinculados" : "Confirma las cuentas sugeridas", href: "/satrapy/configuracion/contabilidad" },
    { label: "Periodo", complete: open > 0, description: open ? `${open} periodo${open === 1 ? "" : "s"} abierto${open === 1 ? "" : "s"}` : "Abre el periodo del corte", href: "/satrapy/contabilidad/periodos" },
    { label: "Apertura", complete: Boolean(opening)||Boolean(approved&&!data.batches.length), description: opening ? "Póliza de apertura creada" : approved&&!data.batches.length ? "Inicio documentado con saldo cero" : "Concilia la balanza o inicia en cero", href: "/satrapy/contabilidad/apertura" },
  ];
  return <div className="accounting-dashboard">
    <section className={`accounting-readiness ${approved && data.accounts.length && open ? "is-ready" : ""}`}>
      <span className="accounting-readiness__icon">{approved && data.accounts.length && open ? <CheckCircle2 size={22} /> : <AlertTriangle size={22} />}</span>
      <div><strong>{approved && data.accounts.length && open ? "Base contable lista" : "Apertura contable en preparación"}</strong><p>{approved && data.accounts.length && open ? "La configuración, el catálogo y el periodo están disponibles." : "Completa los pasos pendientes antes de promover la balanza de apertura."}</p></div>
      <Badge tone={approved && data.accounts.length && open ? "success" : "warning"}>{steps.filter((step) => step.complete).length} de {steps.length} pasos</Badge>
    </section>
    <section className="accounting-kpis">
      <Kpi icon={<Settings2 size={18} />} label="Configuración" value={approved ? `V${approved.version}` : "Pendiente"} detail={approved ? `${approved.base_currency} · corte ${formatDate(approved.cutoff_date)}` : "Sin aprobar"} />
      <Kpi icon={<BookOpen size={18} />} label="Catálogo" value={data.accounts.length.toLocaleString("es-MX")} detail="cuentas canónicas" />
      <Kpi icon={<CircleDollarSign size={18} />} label="Periodos abiertos" value={String(open)} detail={`${data.periods.length} periodos totales`} />
      <Kpi icon={<FileCheck2 size={18} />} label="Pólizas" value={String(posted)} detail="contabilizadas" />
    </section>
    <section className="accounting-progress-card"><header><div><h2>Ruta de apertura</h2><p>Satrapy mantiene el orden necesario para abrir la contabilidad sin duplicar información.</p></div></header><div className="accounting-steps">{steps.map((step, index) => <Link href={step.href} className={step.complete ? "is-complete" : ""} key={step.label}><span>{step.complete ? <CheckCircle2 size={17} /> : index + 1}</span><div><strong>{step.label}</strong><small>{step.description}</small></div><ArrowRight size={15} /></Link>)}</div></section>
  </div>;
}

function Kpi({ icon, label, value, detail }: { icon: React.ReactNode; label: string; value: string; detail: string }) { return <article><span>{icon}{label}</span><strong>{value}</strong><small>{detail}</small></article>; }

function AccountsView({ companyId,accounts,batches,categories,classificationWork,disabled,canConfigure,onRun }: { companyId:string;accounts:Account[];batches:Batch[];categories:ExpenseCategory[];classificationWork:ClassificationWork;disabled:boolean;canConfigure:boolean;onRun:(body:Record<string,unknown>,success:string)=>Promise<void> }) {
  type CategoryDraft={categoryId:string|null;code:string;displayName:string;accountId:string;status:"active"|"inactive";validFrom:string;reason:string};
  const today=()=>new Date().toISOString().slice(0,10);const nextDay=()=>{const value=new Date();value.setUTCDate(value.getUTCDate()+1);return value.toISOString().slice(0,10);};
  const [query,setQuery]=useState("");const [draft,setDraft]=useState<Account|null>(null);const [accountReason,setAccountReason]=useState("");
  const [categoryDraft,setCategoryDraft]=useState<CategoryDraft|null>(null);const [assignments,setAssignments]=useState<Record<string,string>>({});
  const emptyAccount=():Account=>({id:"",code:"",name:"",account_type:"asset",normal_balance:"debit",parent_id:null,level:1,accepts_posting:true,is_active:true,updated_at:""});
  const emptyCategory=():CategoryDraft=>({categoryId:null,code:"",displayName:"",accountId:"",status:"active",validFrom:today(),reason:""});
  const filtered=useMemo(()=>{const normalized=query.trim().toLocaleLowerCase("es-MX");return normalized?accounts.filter(account=>`${account.code} ${account.name}`.toLocaleLowerCase("es-MX").includes(normalized)):accounts;},[accounts,query]);
  const catalog=batches.find(batch=>batch.import_type==="chart_of_accounts"&&batch.status==="staged");
  const expenseAccounts=accounts.filter(account=>account.account_type==="expense"&&account.accepts_posting&&account.is_active);
  const categoryOptions=categories.filter(item=>item.status==="active").map(item=>({value:item.category_id,label:`${item.code} · ${item.display_name}`}));
  async function save(){if(!draft)return;await onRun({action:"save_account",companyId,accountId:draft.id||null,code:draft.code,name:draft.name,accountType:draft.account_type,normalBalance:draft.normal_balance,parentId:draft.parent_id,level:draft.level,acceptsPosting:draft.accepts_posting,isActive:draft.is_active,reason:accountReason,expectedUpdatedAt:draft.updated_at||null,clientRequestId:crypto.randomUUID()},draft.id?"Cuenta actualizada":"Cuenta creada");setDraft(null);setAccountReason("");}
  async function saveCategory(){if(!categoryDraft)return;await onRun({action:"save_expense_category",companyId,categoryId:categoryDraft.categoryId,code:categoryDraft.code,displayName:categoryDraft.displayName,accountId:categoryDraft.accountId,status:categoryDraft.status,validFrom:categoryDraft.validFrom,reason:categoryDraft.reason,clientRequestId:crypto.randomUUID()},categoryDraft.categoryId?"Nueva versión de categoría guardada":"Categoría creada");setCategoryDraft(null);}
  async function assign(item:ClassificationWork["items"][number]){const categoryId=assignments[item.preserved_text];if(!categoryId)return;await onRun({action:"bulk_assign_expense_category",companyId,categoryId,expenseCategoryText:item.preserved_text,limit:1000,clientRequestId:crypto.randomUUID()},"Conceptos clasificados en servidor");}
  return <div className="accounting-stack">
    {catalog&&<section className="accounting-panel"><header><div><h2>Catálogo preparado</h2><p>{catalog.original_name} · {catalog.row_count.toLocaleString("es-MX")} cuentas validadas para agregar o actualizar.</p></div><Badge tone="success">Listo</Badge></header><footer><span>La promoción procesa el catálogo completo; la captura manual es para pocas cuentas.</span><Button variant="primary" loading={disabled} onClick={()=>void onRun({action:"promote",batchId:catalog.id,clientRequestId:crypto.randomUUID()},"Catálogo promovido")}>Promover catálogo</Button></footer></section>}
    <section className="accounting-manual-note"><div><strong>Catálogo administrable y protegido</strong><p>Los nombres siguen siendo comprensibles; una cuenta utilizada conserva tipo, naturaleza, nivel y estructura.</p></div>{canConfigure&&<Button variant="primary" onClick={()=>{setDraft(emptyAccount());setAccountReason("");}}><Plus size={15}/> Nueva cuenta</Button>}</section>
    <DataToolbar search={query} onSearchChange={setQuery} placeholder="Buscar por código o nombre" results={filtered.length}/>
    <DataState loading={false} error={null} hasData={filtered.length} empty={query?"No hay cuentas que coincidan con la búsqueda.":"Crea la primera cuenta o importa un catálogo extenso."}><Table className="accounting-table"><thead><tr><th>Código</th><th>Cuenta</th><th>Tipo</th><th>Naturaleza</th><th>Nivel</th><th>Estado</th></tr></thead><tbody>{filtered.map(account=><tr key={account.id} className={canConfigure?"accounting-account-row":""} onClick={()=>{if(canConfigure){setDraft({...account});setAccountReason("");}}}><td className="mono">{account.code}</td><td><strong>{account.name}</strong>{account.parent_id&&<small>Cuenta dependiente</small>}</td><td>{accountTypeLabel(account.account_type)}</td><td>{account.normal_balance==="debit"?"Deudora":"Acreedora"}</td><td>{account.level}</td><td><Badge tone={account.is_active?"success":"neutral"}>{account.is_active?(account.accepts_posting?"Afectable":"Acumulativa"):"Inactiva"}</Badge></td></tr>)}</tbody></Table></DataState>
    <section className="accounting-panel"><header><div><h2>Categorías de gasto</h2><p>Una categoría explícita resuelve una cuenta aprobada según la fecha de la factura; el texto fiscal original no se reemplaza.</p></div>{canConfigure&&<Button size="sm" variant="primary" onClick={()=>setCategoryDraft(emptyCategory())}><Plus size={14}/> Nueva categoría</Button>}</header><DataState loading={false} error={null} hasData={categories.length} empty="No hay categorías configuradas."><Table><thead><tr><th>Código</th><th>Nombre visible</th><th>Cuenta</th><th>Versión</th><th>Vigencia</th><th>Estado</th></tr></thead><tbody>{categories.map(category=><tr key={category.id} className={canConfigure?"accounting-account-row":""} onClick={()=>canConfigure&&setCategoryDraft({categoryId:category.category_id,code:category.code,displayName:category.display_name,accountId:category.account_id,status:category.status,validFrom:nextDay(),reason:""})}><td className="mono">{category.code}</td><td><strong>{category.display_name}</strong></td><td>{accounts.find(account=>account.id===category.account_id)?.name??"—"}</td><td>V{category.version}</td><td>{formatDate(category.valid_from)}</td><td><Badge tone={category.status==="active"?"success":"neutral"}>{category.status==="active"?"Activa":"Inactiva"}</Badge></td></tr>)}</tbody></Table></DataState></section>
    <section className="accounting-panel"><header><div><h2>Excepciones de clasificación</h2><p>Se agrupan por el texto ya guardado; una acción aplica hasta 1,000 conceptos sin adivinar por descripción, proveedor o clave SAT.</p></div><Badge tone={classificationWork.pagination.total?"warning":"success"}>{classificationWork.pagination.total}</Badge></header><DataState loading={false} error={null} hasData={classificationWork.items.length} empty="No hay conceptos pendientes de categoría vigente."><div className="accounting-card-list">{classificationWork.items.map(item=><article key={item.preserved_text||"__empty"}><AlertTriangle size={17}/><span><strong>{item.preserved_text||"Sin categoría registrada"}</strong><small>{item.line_count.toLocaleString("es-MX")} conceptos · {item.invoice_count.toLocaleString("es-MX")} facturas · desde {formatDate(item.oldest_date)}</small></span>{canConfigure&&<><Select ariaLabel={`Categoría para ${item.preserved_text||"sin categoría"}`} value={assignments[item.preserved_text]??""} onValueChange={value=>setAssignments({...assignments,[item.preserved_text]:value})} placeholder="Selecciona categoría" options={categoryOptions}/><Button size="sm" variant="secondary" disabled={disabled||!assignments[item.preserved_text]} onClick={()=>void assign(item)}>Asignar lote</Button></>}</article>)}</div></DataState></section>
    <Drawer open={Boolean(draft)} onOpenChange={open=>{if(!open&&!disabled){setDraft(null);setAccountReason("");}}} title={draft?.id?"Editar cuenta":"Nueva cuenta"}>{draft&&<form className="accounting-account-form" onSubmit={event=>{event.preventDefault();void save();}}><Field label="Código"><Input required value={draft.code} onChange={event=>setDraft({...draft,code:event.target.value})}/></Field><Field label="Nombre comprensible"><Input required value={draft.name} onChange={event=>setDraft({...draft,name:event.target.value})}/></Field><Field label="Tipo"><Select ariaLabel="Tipo de cuenta" value={draft.account_type} onValueChange={value=>setDraft({...draft,account_type:value})} options={[{value:"asset",label:"Activo"},{value:"liability",label:"Pasivo"},{value:"equity",label:"Capital"},{value:"revenue",label:"Ingresos"},{value:"expense",label:"Gastos"},{value:"memorandum",label:"Orden"}]}/></Field><Field label="Naturaleza"><Select ariaLabel="Naturaleza" value={draft.normal_balance} onValueChange={value=>setDraft({...draft,normal_balance:value})} options={[{value:"debit",label:"Deudora"},{value:"credit",label:"Acreedora"}]}/></Field><Field label="Cuenta padre"><Select ariaLabel="Cuenta padre" value={draft.parent_id??"none"} onValueChange={value=>setDraft({...draft,parent_id:value==="none"?null:value,level:value==="none"?1:(accounts.find(item=>item.id===value)?.level??0)+1})} options={[{value:"none",label:"Sin cuenta padre"},...accounts.filter(item=>item.id!==draft.id).map(item=>({value:item.id,label:`${item.code} · ${item.name}`}))]}/></Field><label><input type="checkbox" checked={draft.accepts_posting} onChange={event=>setDraft({...draft,accepts_posting:event.target.checked})}/> Acepta movimientos</label><label><input type="checkbox" checked={draft.is_active} onChange={event=>setDraft({...draft,is_active:event.target.checked})}/> Cuenta activa</label><Field label="Motivo obligatorio"><Input value={accountReason} onChange={event=>setAccountReason(event.target.value)} placeholder="Explica el alta, cambio o desactivación"/></Field><div className="product-catalog__form-actions"><Button type="button" disabled={disabled} onClick={()=>setDraft(null)}>Cancelar</Button><Button type="submit" variant="primary" loading={disabled} disabled={!draft.code.trim()||!draft.name.trim()||!accountReason.trim()}>Guardar cuenta</Button></div></form>}</Drawer>
    <Drawer open={Boolean(categoryDraft)} onOpenChange={open=>!open&&!disabled&&setCategoryDraft(null)} title={categoryDraft?.categoryId?"Nueva versión de categoría":"Nueva categoría"}>{categoryDraft&&<form className="accounting-account-form" onSubmit={event=>{event.preventDefault();void saveCategory();}}><Field label="Código"><Input required value={categoryDraft.code} onChange={event=>setCategoryDraft({...categoryDraft,code:event.target.value})}/></Field><Field label="Nombre visible"><Input required value={categoryDraft.displayName} onChange={event=>setCategoryDraft({...categoryDraft,displayName:event.target.value})}/></Field><Field label="Cuenta de gasto"><Select ariaLabel="Cuenta de gasto" value={categoryDraft.accountId} onValueChange={accountId=>setCategoryDraft({...categoryDraft,accountId})} placeholder="Selecciona cuenta" options={expenseAccounts.map(account=>({value:account.id,label:`${account.code} · ${account.name}`}))}/></Field><Field label="Estado"><Select ariaLabel="Estado de categoría" value={categoryDraft.status} onValueChange={status=>setCategoryDraft({...categoryDraft,status:status as "active"|"inactive"})} options={[{value:"active",label:"Activa"},{value:"inactive",label:"Inactiva"}]}/></Field><Field label="Vigente desde"><Input type="date" value={categoryDraft.validFrom} onChange={event=>setCategoryDraft({...categoryDraft,validFrom:event.target.value})}/></Field><Field label="Motivo"><Input value={categoryDraft.reason} onChange={event=>setCategoryDraft({...categoryDraft,reason:event.target.value})} placeholder="Explica la versión o desactivación"/></Field><div className="product-catalog__form-actions"><Button type="button" onClick={()=>setCategoryDraft(null)}>Cancelar</Button><Button type="submit" variant="primary" loading={disabled} disabled={!categoryDraft.code.trim()||!categoryDraft.displayName.trim()||!categoryDraft.accountId||!categoryDraft.validFrom||!categoryDraft.reason.trim()}>Guardar versión</Button></div></form>}</Drawer>
  </div>;
}

function PeriodsView({ periods, closeRuns, responsibles, companyId, cutoff, disabled, permissions, onRun }: { periods: Period[];closeRuns:CloseRun[];responsibles:Responsible[];companyId: string; cutoff?: string; disabled: boolean;permissions:string[]; onRun: (body: Record<string, unknown>, success: string) => Promise<void> }) {
  const month = cutoff?.slice(0, 7) ?? ""; const [form, setForm] = useState({ code: month, startsOn: month ? `${month}-01` : "", endsOn: cutoff ?? "" });
  const [confirmation, setConfirmation] = useState<{ period: Period; run: CloseRun; action: "approve" | "confirm" | "reopen" } | null>(null); const [reason, setReason] = useState("");
  const canPrepare=permissions.includes("prepare_accounting_close");const canApprove=permissions.includes("approve_accounting_close");const canClose=permissions.includes("close_accounting_periods");const canReopen=permissions.includes("reopen_accounting_close");const person=(id:string|null)=>responsibles.find(item=>item.id===id)?.name??"Usuario con acceso";
  async function submit(){if(!confirmation||(confirmation.action!=="confirm"&&!reason.trim()))return;const body=confirmation.action==="approve"?{action:"approve_close",closeRunId:confirmation.run.id,reason,clientRequestId:crypto.randomUUID()}:confirmation.action==="confirm"?{action:"confirm_close",closeRunId:confirmation.run.id,clientRequestId:crypto.randomUUID()}:{action:"reopen_close",closeRunId:confirmation.run.id,reason,clientRequestId:crypto.randomUUID()};await onRun(body,confirmation.action==="approve"?"Cierre aprobado":confirmation.action==="confirm"?"Periodo cerrado":"Periodo reabierto");setConfirmation(null);setReason("");}
  return <div className="accounting-period-workspace"><aside className="accounting-period-create"><header><span><CalendarRange size={19}/></span><div><h2>Nuevo periodo</h2><p>Define un rango sin traslapar los existentes.</p></div></header><Field label="Código"><Input placeholder="2026-07" value={form.code} onChange={(event) => setForm({ ...form, code: event.target.value })} /></Field><div className="accounting-period-dates"><Field label="Fecha inicial"><Input type="date" value={form.startsOn} onChange={(event) => setForm({ ...form, startsOn: event.target.value })} /></Field><Field label="Fecha final"><Input type="date" value={form.endsOn} onChange={(event) => setForm({ ...form, endsOn: event.target.value })} /></Field></div><Button variant="primary" disabled={disabled || !form.code || !form.startsOn || !form.endsOn} onClick={() => void onRun({ action: "create_period", companyId, periodCode: form.code, startsOn: form.startsOn, endsOn: form.endsOn }, "Periodo creado")}>Crear periodo</Button><small>La fecha de corte debe quedar dentro de un periodo abierto.</small></aside>
    <div className="accounting-stack"><section className="accounting-readiness is-ready"><span className="accounting-readiness__icon"><CheckCircle2 size={22}/></span><div><strong>Tu acceso al cierre</strong><p>{canPrepare?"Puedes preparar cierres.":"No puedes preparar cierres."} {canApprove&&canClose?"Puedes aprobar y confirmar, pero otra persona debe haber preparado el cierre.":canApprove?"Puedes aprobar cierres preparados por otra persona.":canClose?"Puedes confirmar cierres ya aprobados.":""} {canReopen?"Puedes solicitar reaperturas excepcionales si otra persona confirmó el cierre.":""}</p></div><Badge tone={canPrepare||canApprove||canClose||canReopen?"success":"warning"}>{canPrepare||canApprove||canClose||canReopen?"Acceso disponible":"Sólo consulta"}</Badge></section>
    <section className="accounting-panel accounting-close-board"><header><div><h2>Periodos contables</h2><p>El cierre revisa conciliaciones antes de bloquear el periodo; preparar no modifica saldos.</p></div><Badge>{periods.length} periodos</Badge></header><DataState loading={false} error={null} hasData={periods.length} empty="Aún no hay periodos contables."><div className="accounting-close-list">{periods.map(period=>{const run=closeRuns.find(item=>item.period_id===period.id);const failed=run?.snapshot.checks?.filter(check=>check.blocking&&!check.passed)??[];const next=!run?"Preparar cierre":run.status==="prepared"?"Requiere aprobación de otra persona":run.status==="approved"?(failed.length?"Bloqueado por diferencias contables":"Listo para confirmar"):run.status==="closed"?"Cerrado":"Requiere preparar un nuevo cierre";return <article className="accounting-close-card" key={period.id}><header><div className="accounting-period-identity"><span>{period.period_code.slice(0,7)}</span><div><strong>{period.period_code}</strong><small>{formatDate(period.starts_on)} — {formatDate(period.ends_on)}</small>{run&&<small>Vista {run.snapshot_sha256.slice(0,12)} · {failed.length?failed.map(check=>closeCheckLabel(check.code)).join(", "):"Sin diferencias bloqueantes"}</small>}</div></div><div className="accounting-period-actions"><Badge tone={period.status==="open"?"success":"neutral"}>{period.status==="open"?"Abierto":"Cerrado"}</Badge>{!run&&period.status==="open"&&canPrepare&&<Button size="sm" variant="secondary" disabled={disabled} onClick={()=>void onRun({action:"prepare_close",companyId,periodId:period.id,clientRequestId:crypto.randomUUID()},"Cierre preparado")}>Preparar cierre</Button>}{run?.status==="prepared"&&canApprove&&<Button size="sm" variant="secondary" disabled={disabled} onClick={()=>setConfirmation({period,run,action:"approve"})}>Aprobar</Button>}{run?.status==="approved"&&canClose&&<Button size="sm" variant="primary" disabled={disabled||failed.length>0} onClick={()=>setConfirmation({period,run,action:"confirm"})}>Confirmar cierre</Button>}{run?.status==="closed"&&canReopen&&<Button size="sm" variant="secondary" disabled={disabled} onClick={()=>setConfirmation({period,run,action:"reopen"})}>Reabrir excepcionalmente</Button>}</div></header><div className="accounting-close-summary"><span><small>Siguiente paso</small><b>{next}</b></span>{run&&<><span><small>Estado</small><b>{closeStatusLabel(run.status)}</b></span><span><small>Preparó</small><b>{person(run.prepared_by)} · {formatDate(run.prepared_at)}</b></span>{run.approved_at&&<span><small>Aprobó</small><b>{person(run.approved_by)} · {formatDate(run.approved_at)}</b></span>}{run.reopen_reason&&<span><small>Motivo de reapertura</small><b>{run.reopen_reason}</b></span>}</>}</div></article>;})}</div></DataState></section></div>
    <Modal open={Boolean(confirmation)} onOpenChange={open=>{if(!open){setConfirmation(null);setReason("");}}} eyebrow="Cierre protegido" title={`${confirmation?.action==="approve"?"Aprobar":confirmation?.action==="confirm"?"Confirmar cierre":"Reabrir"} ${confirmation?.period.period_code??"periodo"}`} description={confirmation?.action==="approve"?"La aprobación requiere una persona distinta de quien preparó el cierre.":confirmation?.action==="confirm"?"Esta acción bloquea atómicamente el periodo si la vista previa no cambió y no hay diferencias.":"La reapertura es excepcional, exige otra persona y preserva la evidencia."} footer={<><Button onClick={()=>setConfirmation(null)}>Cancelar</Button><Button variant="primary" loading={disabled} disabled={confirmation?.action!=="confirm"&&!reason.trim()} onClick={()=>void submit()}>Confirmar</Button></>}>{confirmation?.action!=="confirm"&&<Field label="Motivo" hint="Obligatorio para auditoría"><Input value={reason} onChange={event=>setReason(event.target.value)} placeholder="Describe el motivo"/></Field>}</Modal>
  </div>;
}

function ReportsView({companyId,accounts,periods,locations}:{companyId:string;accounts:Account[];periods:Period[];locations:Location[]}){
  const latest=periods[0];const [reportType,setReportType]=useState("trial_balance");const [startsOn,setStartsOn]=useState(latest?.starts_on??"");const [endsOn,setEndsOn]=useState(latest?.ends_on??"");const [accountId,setAccountId]=useState("");const [locationId,setLocationId]=useState("");const [unassigned,setUnassigned]=useState(false);const [result,setResult]=useState<ReportResult|null>(null);const [loading,setLoading]=useState(false);const [exporting,setExporting]=useState<"xlsx"|"pdf"|null>(null);const [error,setError]=useState<string|null>(null);
  const reportOptions=[{value:"enterprise_consolidated",label:"Consolidado empresarial"},{value:"general_ledger",label:"Mayor por cuenta"},{value:"auxiliaries",label:"Auxiliares"},{value:"trial_balance",label:"Balanza de comprobación"},{value:"income_statement",label:"Estado de resultados"},{value:"balance_sheet",label:"Balance general"},{value:"cash_flow",label:"Entradas y salidas de efectivo"}];const administrative=locationId||unassigned;
  async function loadReport(page=1){setLoading(true);setError(null);try{const session=(await getSupabaseClient().auth.getSession()).data.session;if(!session)throw new Error("Sesión no válida.");const params=new URLSearchParams({companyId,reportType,startsOn,endsOn,page:String(page),pageSize:"50"});if(accountId&&!administrative)params.set("accountId",accountId);if(locationId)params.set("locationId",locationId);if(unassigned)params.set("unassigned","true");const response=await fetch(`/api/imports/accounting?${params}`,{headers:{Authorization:`Bearer ${session.access_token}`},cache:"no-store"});const body=await response.json();if(!response.ok)throw new Error(body.message??"No se pudo generar el estado.");setResult(body);}catch(value){setError(value instanceof Error?value.message:"No se pudo generar el estado.");}finally{setLoading(false);}}
  async function downloadReport(format:"xlsx"|"pdf"){setExporting(format);setError(null);try{const session=(await getSupabaseClient().auth.getSession()).data.session;if(!session)throw new Error("Sesión no válida.");const params=new URLSearchParams({companyId,reportType,startsOn,endsOn,format});if(accountId&&!administrative)params.set("accountId",accountId);if(locationId)params.set("locationId",locationId);if(unassigned)params.set("unassigned","true");const response=await fetch(`/api/imports/accounting/export?${params}`,{headers:{Authorization:`Bearer ${session.access_token}`},cache:"no-store"});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.message??"No se pudo generar la descarga.");}const blob=await response.blob();const disposition=response.headers.get("content-disposition")??"";const filename=disposition.match(/filename="([^"]+)"/)?.[1]??`estado_financiero.${format}`;const url=URL.createObjectURL(blob);const anchor=document.createElement("a");anchor.href=url;anchor.download=filename;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);}catch(value){setError(value instanceof Error?value.message:"No se pudo generar la descarga.");}finally{setExporting(null);}}
  const selectedLabel=reportOptions.find((item)=>item.value===reportType)?.label??"Estado financiero";
  return <div className="accounting-stack"><section className="accounting-report-builder"><header><div><span><BarChart3 size={19}/></span><div><h2>Preparar reporte</h2><p>Selecciona el estado y el periodo que quieres consultar.</p></div></div><Badge tone={administrative?"warning":"info"}>{administrative?"Vista administrativa":"Datos del libro"}</Badge></header><div className="accounting-report-builder__body"><div className="accounting-report-kind"><Field label="Tipo de reporte"><Select ariaLabel="Estado financiero" value={reportType} onValueChange={(value)=>{setReportType(value);setResult(null);}} options={reportOptions}/></Field><div><strong>{selectedLabel}</strong><small>{reportDescription(reportType)}</small></div>{reportType==="general_ledger"&&!administrative&&<Field label="Cuenta"><Select ariaLabel="Cuenta del mayor" value={accountId} onValueChange={setAccountId} placeholder="Todas las cuentas" options={accounts.map((account)=>({value:account.id,label:`${account.code} · ${account.name}`}))}/></Field>}<Field label="Vista por ubicación"><Select ariaLabel="Ubicación administrativa" value={unassigned?"__unassigned":locationId||"__all"} onValueChange={value=>{setResult(null);setUnassigned(value==="__unassigned");setLocationId(value==="__all"||value==="__unassigned"?"":value);}} options={[{value:"__all",label:"Consolidado empresarial"},{value:"__unassigned",label:"Sin asignar"},...locations.map(location=>({value:location.id,label:`${location.external_code} · ${location.name}`}))]}/><small>Los filtros por ubicación no sustituyen al consolidado oficial.</small></Field></div><div className="accounting-report-range"><span className="eyebrow">Periodo del reporte</span><div><Field label="Desde"><Input type="date" value={startsOn} onChange={(event)=>setStartsOn(event.target.value)}/></Field><Field label="Hasta"><Input type="date" value={endsOn} onChange={(event)=>setEndsOn(event.target.value)}/></Field></div><Button variant="primary" loading={loading} disabled={!startsOn||!endsOn} onClick={()=>void loadReport()}><BarChart3 size={15}/> Generar reporte</Button></div></div><footer><CheckCircle2 size={15}/><span>{administrative?"Filtro administrativo por ubicación; el consolidado empresarial sigue siendo el reporte oficial.":"Se calcula en servidor desde pólizas contabilizadas; no requiere archivos adicionales."}</span></footer></section>{error&&<section className="accounting-readiness"><AlertTriangle size={20}/><div><strong>No se pudo generar</strong><p>{error}</p></div></section>}{result&&<FinancialReport result={result} exporting={exporting} onDownload={downloadReport} onPage={loadReport}/>}</div>;
}

function FinancialReport({result,exporting,onDownload,onPage}:{result:ReportResult;exporting:"xlsx"|"pdf"|null;onDownload:(format:"xlsx"|"pdf")=>Promise<void>;onPage:(page:number)=>Promise<void>}){const rows=result.rows;const keys=accountingReportKeys(rows);const pages=Math.max(1,Math.ceil(result.total/result.page_size));const totals=Object.entries(result.totals??{});return <section className="accounting-panel accounting-report-result"><header><div><h2>{reportLabel(result.report_type)}</h2><p>{formatDate(result.starts_on)} — {formatDate(result.ends_on)} · {result.total.toLocaleString("es-MX")} renglones</p></div><div className="accounting-report-actions"><Badge tone={result.balanced===false?"warning":"success"}>{result.balanced===false?"No cuadra":"Generado"}</Badge><Button size="sm" variant="secondary" loading={exporting==="xlsx"} disabled={Boolean(exporting)} onClick={()=>void onDownload("xlsx")}><FileSpreadsheet size={14}/> Excel</Button><Button size="sm" variant="secondary" loading={exporting==="pdf"} disabled={Boolean(exporting)} onClick={()=>void onDownload("pdf")}><FileText size={14}/> PDF</Button></div></header>{totals.length>0&&<div className="accounting-close-summary">{totals.map(([key,value])=><span key={key}><small>{reportColumnLabel(key)}</small><b>{money(Number(value))}</b></span>)}</div>}<DataState loading={false} error={null} hasData={rows.length} empty="No existen movimientos para este rango."><Table><thead><tr>{keys.map((key)=><th className={isAmountKey(key)?"number-cell":undefined} key={key}>{reportColumnLabel(key)}</th>)}</tr></thead><tbody>{rows.map((row,index)=><tr key={`${result.page}-${index}`}>{keys.map((key)=><td className={isAmountKey(key)?"number-cell":undefined} key={key}>{formatReportValue(key,row[key])}</td>)}</tr>)}</tbody></Table></DataState>{pages>1&&<footer><span>Página {result.page} de {pages}</span><Button size="sm" disabled={result.page<=1} onClick={()=>void onPage(result.page-1)}>Anterior</Button><Button size="sm" disabled={result.page>=pages} onClick={()=>void onPage(result.page+1)}>Siguiente</Button></footer>}</section>}

function JournalsView({companyId,journals,accounts,adjustments,permissions,disabled,onRun}:{companyId:string;journals:Journal[];accounts:Account[];adjustments:ManualAdjustment[];permissions:string[];disabled:boolean;onRun:(body:Record<string,unknown>,success:string)=>Promise<void>}) {
  const names = new Map(accounts.map((item) => [item.id, `${item.code} · ${item.name}`]));
  const accountOptions=accounts.filter((item)=>item.accepts_posting).map((item)=>({value:item.id,label:`${item.code} · ${item.name}`}));const [open,setOpen]=useState(false);const [form,setForm]=useState({type:"reclassification",date:new Date().toISOString().slice(0,10),description:"",reason:"",debitAccount:"",creditAccount:"",amount:""});const [decision,setDecision]=useState<{item:ManualAdjustment;action:"approve"|"reject"|"reverse"}|null>(null);const [decisionReason,setDecisionReason]=useState("");
  async function submit(){await onRun({action:"submit_adjustment",companyId,adjustmentType:form.type,entryDate:form.date,description:form.description,reason:form.reason,lines:[{line_number:1,account_id:form.debitAccount,debit:Number(form.amount),credit:0},{line_number:2,account_id:form.creditAccount,debit:0,credit:Number(form.amount)}],clientRequestId:crypto.randomUUID()},"Ajuste enviado a aprobación");setOpen(false);}
  async function decide(){if(!decision)return;if(decision.action==="reverse")await onRun({action:"reverse_adjustment",adjustmentId:decision.item.id,entryDate:new Date().toISOString().slice(0,10),reason:decisionReason,clientRequestId:crypto.randomUUID()},"Ajuste revertido");else await onRun({action:"decide_adjustment",adjustmentId:decision.item.id,decision:decision.action,reason:decisionReason,clientRequestId:crypto.randomUUID()},decision.action==="approve"?"Ajuste aprobado":"Ajuste rechazado");setDecision(null);setDecisionReason("");}
  return <div className="accounting-stack"><section className="accounting-panel"><header><div><h2>Ajustes manuales</h2><p>Uso excepcional para reclasificaciones, correcciones y cierre. Quien solicita no puede aprobar.</p></div>{permissions.includes("post_accounting_adjustments")&&<Button size="sm" variant="secondary" onClick={()=>setOpen(true)}>Solicitar ajuste</Button>}</header><DataState loading={false} error={null} hasData={adjustments.length} empty="No hay ajustes manuales solicitados."><div className="accounting-period-list">{adjustments.map((item)=><article key={item.id}><div><strong>{item.description}</strong><small>{formatDate(item.entry_date)} · {manualTypeLabel(item.adjustment_type)}</small></div><Badge tone={item.status==="approved"?"success":item.status==="submitted"?"warning":"neutral"}>{manualStatusLabel(item.status)}</Badge>{item.status==="submitted"&&permissions.includes("approve_accounting_adjustments")&&<><Button size="sm" variant="secondary" onClick={()=>setDecision({item,action:"reject"})}>Rechazar</Button><Button size="sm" variant="primary" onClick={()=>setDecision({item,action:"approve"})}>Aprobar</Button></>}{item.status==="approved"&&permissions.includes("reverse_accounting_adjustments")&&<Button size="sm" variant="secondary" onClick={()=>setDecision({item,action:"reverse"})}>Revertir</Button>}</article>)}</div></DataState></section><DataState loading={false} error={null} hasData={journals.length} empty="Aún no hay pólizas contabilizadas. La primera será la póliza de apertura."><div className="accounting-journals">{journals.map((journal) => { const debit = journal.accounting_journal_lines.reduce((sum, line) => sum + Number(line.debit), 0); const credit = journal.accounting_journal_lines.reduce((sum, line) => sum + Number(line.credit), 0); return <article className="accounting-journal" key={journal.id}><header><div><span className="eyebrow">Póliza {journal.entry_number}</span><h2>{journal.description}</h2><p>{formatDate(journal.entry_date)} · {journal.source_type === "opening" ? "Apertura" : journal.source_type==="operational_event"?"Evento automático":"Ajuste manual"}</p></div><div><Badge tone="success">Contabilizada</Badge>{journal.immutable && <Badge tone="neutral">Inmutable</Badge>}</div></header><Table><thead><tr><th>Cuenta</th><th>Descripción</th><th className="number-cell">Debe</th><th className="number-cell">Haber</th></tr></thead><tbody>{journal.accounting_journal_lines.map((line) => <tr key={line.id}><td><strong>{names.get(line.account_id) ?? line.external_account_code}</strong></td><td>{line.description ?? "—"}</td><td className="number-cell">{money(line.debit)}</td><td className="number-cell">{money(line.credit)}</td></tr>)}</tbody><tfoot><tr><td colSpan={2}><strong>Totales</strong></td><td className="number-cell"><strong>{money(debit)}</strong></td><td className="number-cell"><strong>{money(credit)}</strong></td></tr></tfoot></Table></article>; })}</div></DataState><Modal open={open} onOpenChange={setOpen} eyebrow="Póliza manual" title="Solicitar ajuste" description="Captura solo un ajuste simple de dos cuentas; Satrapy validará doble entrada y lo enviará a otra persona." footer={<><Button onClick={()=>setOpen(false)}>Cancelar</Button><Button variant="primary" loading={disabled} disabled={!form.date||!form.description.trim()||!form.reason.trim()||!form.debitAccount||!form.creditAccount||Number(form.amount)<=0||form.debitAccount===form.creditAccount} onClick={()=>void submit()}>Enviar a aprobación</Button></>}><div className="accounting-form-grid is-two"><Field label="Tipo"><Select ariaLabel="Tipo de ajuste" value={form.type} onValueChange={(type)=>setForm({...form,type})} options={[{value:"reclassification",label:"Reclasificación"},{value:"correction",label:"Corrección"},{value:"closing_adjustment",label:"Ajuste de cierre"}]}/></Field><Field label="Fecha"><Input type="date" value={form.date} onChange={(event)=>setForm({...form,date:event.target.value})}/></Field><Field label="Cuenta de cargo"><Select ariaLabel="Cuenta de cargo" value={form.debitAccount} onValueChange={(debitAccount)=>setForm({...form,debitAccount})} placeholder="Selecciona cuenta" options={accountOptions}/></Field><Field label="Cuenta de abono"><Select ariaLabel="Cuenta de abono" value={form.creditAccount} onValueChange={(creditAccount)=>setForm({...form,creditAccount})} placeholder="Selecciona cuenta" options={accountOptions}/></Field><Field label="Importe"><Input type="number" min="0.01" step="0.01" value={form.amount} onChange={(event)=>setForm({...form,amount:event.target.value})}/></Field><Field label="Descripción"><Input value={form.description} onChange={(event)=>setForm({...form,description:event.target.value})} placeholder="Qué se ajusta"/></Field></div><Field label="Motivo y evidencia"><Input value={form.reason} onChange={(event)=>setForm({...form,reason:event.target.value})} placeholder="Referencia o justificación"/></Field></Modal><Modal open={Boolean(decision)} onOpenChange={(value)=>{if(!value){setDecision(null);setDecisionReason("");}}} eyebrow="Control independiente" title={decision?.action==="approve"?"Aprobar ajuste":decision?.action==="reject"?"Rechazar ajuste":"Revertir ajuste"} description={decision?.action==="reverse"?"Se creará una póliza inversa; la original no se edita ni elimina.":"La decisión quedará registrada en auditoría."} footer={<><Button onClick={()=>setDecision(null)}>Cancelar</Button><Button variant="primary" loading={disabled} disabled={!decisionReason.trim()} onClick={()=>void decide()}>Confirmar</Button></>}><Field label="Motivo"><Input value={decisionReason} onChange={(event)=>setDecisionReason(event.target.value)} placeholder="Describe la decisión"/></Field></Modal></div>;
}

function EventsView({companyId,accounts,ruleSets,roleAccounts,events,disabled,canConfigure,canReprocess,onRun}:{companyId:string;accounts:Account[];ruleSets:EventRuleSet[];roleAccounts:EventRoleAccount[];events:AccountingEvent[];disabled:boolean;canConfigure:boolean;canReprocess:boolean;onRun:(body:Record<string,unknown>,success:string)=>Promise<void>}){
  const approved=ruleSets.find((item)=>item.status==="approved");const draft=ruleSets.find((item)=>item.status==="draft");const active=draft??approved;
  const saved=Object.fromEntries(roleAccounts.filter((item)=>item.rule_set_id===active?.id).map((item)=>[item.account_role,item.account_id]));
  const suggested=Object.fromEntries(eventRoleKeys.map((key)=>[key,suggestEventAccount(key,accounts)?.id??""]));
  const [selected,setSelected]=useState<Record<string,string>>(Object.keys(saved).length?saved:suggested);const [costMethod,setCostMethod]=useState("replacement_cost");const [reason,setReason]=useState("");
  const posted=events.filter((item)=>item.status==="posted").length;const pending=events.filter((item)=>item.status==="pending").length;const reversals=events.filter((item)=>item.original_event_id).length;
  if(!active)return <div className="accounting-settings-layout"><aside className="accounting-guide"><span><Workflow size={20}/></span><h2>Ruta operativa</h2><p>La matriz se define una sola vez; después Satrapy contabiliza desde los documentos originales.</p><ol><li className="is-active"><b>1</b><span><strong>Elegir costo</strong><small>Política de inventario</small></span></li><li><b>2</b><span><strong>Vincular cuentas</strong><small>Por evento económico</small></span></li><li><b>3</b><span><strong>Activar motor</strong><small>Con trazabilidad</small></span></li></ol></aside><section className="accounting-panel"><header><div><h2>Crear matriz operativa</h2><p>Esto no duplica pólizas ni modifica la apertura; prepara las reglas para ventas, caja, inventario y compras.</p></div><Badge tone="warning">Pendiente</Badge></header><div className="accounting-form-grid is-two"><Field label="Método de costo"><Select ariaLabel="Método de costo" value={costMethod} onValueChange={setCostMethod} options={[{value:"replacement_cost",label:"Costo de reposición"},{value:"average_cost",label:"Costo promedio"},{value:"standard_cost",label:"Costo estándar"}]}/></Field><Field label="Motivo" hint="Queda en auditoría"><Input value={reason} onChange={(event)=>setReason(event.target.value)} placeholder="Ej. Política contable aprobada"/></Field></div><footer><span>Se crea un borrador; todavía no contabiliza operaciones.</span><Button variant="primary" loading={disabled} disabled={disabled||!canConfigure||!reason.trim()} onClick={()=>void onRun({action:"create_event_matrix",companyId,costMethod,reason},"Matriz creada")}>Continuar a cuentas</Button></footer></section></div>;
  if(draft)return <div className="accounting-settings-layout"><aside className="accounting-guide"><span><Workflow size={20}/></span><h2>Ruta operativa</h2><p>Confirma las contrapartidas sugeridas antes de activar el motor.</p><ol><li className="is-complete"><b><CheckCircle2 size={15}/></b><span><strong>Método elegido</strong><small>{costMethodLabel(draft.cost_method)}</small></span></li><li className="is-active"><b>2</b><span><strong>Vincular cuentas</strong><small>{eventRoleKeys.filter((key)=>selected[key]).length} de {eventRoleKeys.length}</small></span></li><li><b>3</b><span><strong>Activar motor</strong><small>Una sola aprobación</small></span></li></ol></aside><section className="accounting-panel"><header><div><h2>Cuentas por evento</h2><p>Solo se muestran cuentas afectables. La aprobación guarda toda la matriz en una transacción.</p></div><Badge tone="warning">Borrador V{draft.version}</Badge></header><div className="accounting-control-form">{eventRoleKeys.map((key)=><Field label={eventRoleLabels[key]} key={key}><Select ariaLabel={eventRoleLabels[key]} value={selected[key]??""} onValueChange={(value)=>setSelected({...selected,[key]:value})} placeholder="Selecciona una cuenta" options={accounts.filter((item)=>item.accepts_posting).map((account)=>({value:account.id,label:`${account.code} · ${account.name}`}))}/></Field>)}</div><Field label="Motivo de aprobación"><Input value={reason} onChange={(event)=>setReason(event.target.value)} placeholder="Ej. Validado con el responsable contable"/></Field><footer><span>Al activar, todo evento nuevo deberá producir una póliza válida o la operación se rechazará.</span><Button variant="primary" loading={disabled} disabled={disabled||!canConfigure||!reason.trim()||!eventRoleKeys.every((key)=>selected[key])} onClick={()=>void onRun({action:"complete_event_matrix",ruleSetId:draft.id,roleAccounts:selected,reason},"Motor contable activado")}>Guardar y activar</Button></footer></section></div>;
  return <div className="accounting-stack"><section className="accounting-readiness is-ready"><span className="accounting-readiness__icon"><CheckCircle2 size={22}/></span><div><strong>Contabilización operativa activa</strong><p>Matriz V{approved?.version} · {costMethodLabel(approved?.cost_method??"")} · cada documento conserva vínculo con su póliza.</p></div><Badge tone="success">En operación</Badge></section><section className="accounting-kpis"><Kpi icon={<Workflow size={18}/>} label="Eventos" value={String(events.length)} detail="detectados"/><Kpi icon={<FileCheck2 size={18}/>} label="Contabilizados" value={String(posted)} detail="con póliza"/><Kpi icon={<AlertTriangle size={18}/>} label="Pendientes" value={String(pending)} detail="para reproceso"/><Kpi icon={<RefreshCw size={18}/>} label="Reversas" value={String(reversals)} detail="efecto neutralizado"/></section><section className="accounting-panel"><header><div><h2>Trazabilidad reciente</h2><p>Una fila por evento económico; el origen y la póliza quedan enlazados.</p></div>{pending>0&&canReprocess&&<Button size="sm" variant="secondary" loading={disabled} onClick={()=>void onRun({action:"reprocess_events",companyId},"Eventos reprocesados")}><RefreshCw size={14}/> Reprocesar pendientes</Button>}</header><DataState loading={false} error={null} hasData={events.length} empty="Aún no hay eventos operativos posteriores a la activación."><Table><thead><tr><th>Evento</th><th>Fecha</th><th>Origen</th><th>Póliza</th><th>Estado</th></tr></thead><tbody>{events.map((event)=>{const journal=Array.isArray(event.accounting_journal_entries)?event.accounting_journal_entries[0]:event.accounting_journal_entries;return <tr key={event.id}><td><strong>{eventTypeLabel(event.event_type)}</strong>{event.original_event_id&&<small>Reversa exacta</small>}</td><td>{formatDate(event.accounting_date)}</td><td>{sourceTypeLabel(event.source_entity_type)}</td><td>{journal?`#${journal.entry_number}`:"—"}</td><td><Badge tone={event.status==="posted"?"success":"warning"}>{event.status==="posted"?"Contabilizado":"Pendiente"}</Badge></td></tr>;})}</tbody></Table></DataState></section><section className="accounting-panel"><header><div><h2>Matriz vigente</h2><p>Las cuentas de control provienen de la configuración contable; aquí se muestran las contrapartidas adicionales.</p></div><Badge>{eventRoleKeys.length}</Badge></header><div className="accounting-control-grid">{eventRoleKeys.map((key)=><article key={key}><span>{eventRoleLabels[key]}</span><strong>{accounts.find((account)=>account.id===roleAccounts.find((item)=>item.rule_set_id===approved?.id&&item.account_role===key)?.account_id)?.name??"Sin cuenta"}</strong></article>)}</div></section></div>;
}

function OpeningView({ data, approved, hasPeriod, disabled, onRun }: { data: Payload; approved?: Config; hasPeriod: boolean; disabled: boolean; onRun: (body: Record<string, unknown>, success: string) => Promise<void> }) {
  const [mapping, setMapping] = useState<Record<string, { accountId: string; reason: string }>>({});
  return <div className="accounting-stack"><section className="accounting-migration-callout"><span><UploadCloud size={22} /></span><div><strong>La carga se realiza únicamente en el Centro de Migración</strong><p>Sube catálogo y balanza en el Centro de Migración. Satrapy los detecta automáticamente y trae aquí el resultado para conciliar.</p></div><Link className="ui-button ui-button--secondary ui-button--md" href="/satrapy/configuracion/importaciones">Ir al Centro de Migración <ArrowRight size={15} /></Link></section>
    <DataState loading={false} error={null} hasData={data.batches.length} empty="Todavía no hay archivos contables detectados. Súbelos en el Centro de Migración.">{data.batches.map((batch) => { const exceptions = data.exceptions.filter((item) => item.batch_id === batch.id); const comparisons = data.comparisons.filter((item) => item.batch_id === batch.id); const waiting = batch.status === "awaiting_metadata" || batch.status === "awaiting_configuration"; return <article className="accounting-batch" key={batch.id}><header><div><span className="eyebrow">{batch.import_type === "chart_of_accounts" ? "Catálogo contable" : "Balanza de apertura"}</span><h2>{batch.original_name}</h2><p>{formatDate(batch.cutoff_date)} · {batch.currency_code ?? "Moneda por confirmar"} · {batch.row_count.toLocaleString("es-MX")} filas</p></div><Badge tone={batch.status === "promoted" ? "success" : batch.status === "staged" || waiting ? "warning" : "danger"}>{batch.status === "promoted" ? "Promovido" : waiting ? "Esperando paso previo" : batch.status === "staged" ? "En revisión" : "Con errores"}</Badge></header>{waiting && <div className="accounting-exceptions"><p>El staging está guardado. Confirma los datos detectados y completa los pasos anteriores; no necesitas volver a subir el archivo.</p></div>}{comparisons.length > 0 && <div className="accounting-comparisons">{comparisons.map((item) => <article className={Number(item.difference) === 0 ? "is-balanced" : "is-different"} key={item.control_key}><span>{controlLabels[item.control_key] ?? item.control_key}</span><strong>{money(item.ledger_amount)}</strong><small>Auxiliar {money(item.auxiliary_amount)} · Diferencia {money(item.difference)}</small></article>)}</div>}{exceptions.length > 0 && <div className="accounting-exceptions"><h3>Excepciones por resolver</h3>{exceptions.map((item) => { const relation = Array.isArray(item.accounting_import_rows) ? item.accounting_import_rows[0] : item.accounting_import_rows; const external = relation?.external_account_code; const current = mapping[item.id] ?? { accountId: "", reason: "" }; return <div className="accounting-exception" key={item.id}><div><Badge tone="danger">{item.exception_code}</Badge><p>{item.message}</p></div>{item.exception_code === "UNMAPPED_ACCOUNT" && external && <div className="accounting-map-controls"><Select ariaLabel={`Cuenta para ${external}`} value={current.accountId} onValueChange={(accountId) => setMapping({ ...mapping, [item.id]: { ...current, accountId } })} placeholder={`Mapear ${external}`} options={data.accounts.filter((account) => account.accepts_posting).map((account) => ({ value: account.id, label: `${account.code} · ${account.name}` }))} /><Input aria-label={`Motivo para ${external}`} value={current.reason} onChange={(event) => setMapping({ ...mapping, [item.id]: { ...current, reason: event.target.value } })} placeholder="Motivo del mapeo" /><Button size="sm" disabled={disabled || !current.accountId || !current.reason.trim()} onClick={() => void onRun({ action: "map", batchId: batch.id, externalCode: external, accountId: current.accountId, reason: current.reason }, "Cuenta mapeada y lote revalidado")}>Guardar mapeo</Button></div>}</div>; })}</div>}{batch.import_type === "trial_balance" && batch.status === "staged" && <footer><span>{approved && hasPeriod ? "Conciliación lista; la promoción genera una póliza inmutable." : "Aprueba configuración y abre el periodo antes de promover."}</span><Button variant="primary" loading={disabled} disabled={disabled || !approved || !hasPeriod} onClick={() => void onRun({ action: "promote", batchId: batch.id, clientRequestId: crypto.randomUUID() }, "Póliza de apertura creada")}>Crear póliza de apertura</Button></footer>}</article>; })}</DataState>
  </div>;
}

function SettingsView({ companyId, data, accounts, approved, draft, controls, disabled, canConfigure, onRun }: { companyId: string; data: Payload; accounts: Account[]; approved?: Config; draft?: Config; controls: Control[]; disabled: boolean; canConfigure:boolean; onRun: (body: Record<string, unknown>, success: string) => Promise<void> }) {
  const balanceBatch = dataBatch("trial_balance"); const catalogBatch = dataBatch("chart_of_accounts"); const source = balanceBatch ?? catalogBatch;
  const [revisionOpen,setRevisionOpen]=useState(false);const [revisionReason,setRevisionReason]=useState("");
  const [baseCurrency, setBaseCurrency] = useState(source?.currency_code ?? ""); const [cutoff, setCutoff] = useState(source?.cutoff_date ?? ""); const [format, setFormat] = useState(catalogBatch?.catalog_structure.format ?? ""); const [correctionReason, setCorrectionReason] = useState(""); const [approvalReason, setApprovalReason] = useState("");
  const [tax, setTax] = useState<Record<string, string>>({ vat_pending: "effective_cash_flow", vat_collected: "on_collection", vat_paid: "on_payment", withholdings: "separate_by_tax" });
  const firstResponsible=data.responsibles[0]?.id??"";const [responsible, setResponsible] = useState<Record<string, string>>({ adjustments: firstResponsible, close: firstResponsible, reopen: firstResponsible });
  const savedControls = Object.fromEntries(controls.filter((item) => item.config_version_id === (draft?.id ?? approved?.id)).map((item) => [item.control_key, item.account_id])); const suggestedControls=Object.fromEntries(controlKeys.map((key)=>[key,suggestControlAccount(key,accounts)?.id??""]));const [selected, setSelected] = useState<Record<string, string>>(Object.keys(savedControls).length?savedControls:suggestedControls);
  if (approved&&!draft) return <div className="accounting-stack"><section className="accounting-readiness is-ready"><span className="accounting-readiness__icon"><CheckCircle2 size={22} /></span><div><strong>Configuración aprobada</strong><p>Versión {approved.version} · {approved.base_currency} · corte {formatDate(approved.cutoff_date)}. La versión vigente no se modifica directamente.</p></div><Badge tone="success">Vigente</Badge>{canConfigure&&<Button variant="secondary" disabled={disabled} onClick={()=>setRevisionOpen(true)}>Crear nueva versión</Button>}</section><section className="accounting-panel"><header><div><h2>Datos vigentes</h2><p>Consulta la base, el tratamiento fiscal, responsables y cuentas que gobiernan la operación actual.</p></div><Badge>Versión {approved.version}</Badge></header><div className="accounting-config-summary"><article><span>Moneda</span><strong>{approved.base_currency}</strong></article><article><span>Fecha de corte</span><strong>{formatDate(approved.cutoff_date)}</strong></article><article><span>Estructura</span><strong>{approved.catalog_structure.format??"—"}</strong></article><article><span>Última aprobación</span><strong>{formatDate(approved.approved_at)}</strong></article></div><div className="accounting-control-grid">{controlKeys.map((key) => <article key={key}><span>{controlLabels[key]}</span><strong>{accounts.find((account) => account.id === controls.find((item) => item.config_version_id === approved.id && item.control_key === key)?.account_id)?.name ?? "Sin cuenta"}</strong></article>)}</div></section><Modal open={revisionOpen} onOpenChange={setRevisionOpen} eyebrow="Control de cambios" title="Crear nueva versión" description="La versión vigente seguirá operando hasta que apruebes la nueva. Ningún periodo anterior se reescribe." footer={<><Button onClick={()=>setRevisionOpen(false)}>Cancelar</Button><Button variant="primary" loading={disabled} disabled={!revisionReason.trim()} onClick={()=>void onRun({action:"start_config_revision",companyId,reason:revisionReason,clientRequestId:crypto.randomUUID()},"Nueva versión preparada")}>Crear borrador</Button></>}><Field label="Motivo del cambio" hint="Quedará registrado en auditoría"><Input value={revisionReason} onChange={(event)=>setRevisionReason(event.target.value)} placeholder="Ej. Actualización de responsables y cuentas de control"/></Field></Modal></div>;
  if(approved&&draft)return <AccountingRevisionForm draft={draft} approved={approved} accounts={accounts} controls={controls} responsibles={data.responsibles} disabled={disabled} canConfigure={canConfigure} onRun={onRun}/>;
  if (draft && !accounts.length) return <section className="accounting-readiness"><span className="accounting-readiness__icon"><BookOpen size={22} /></span><div><strong>Base confirmada; sigue el catálogo</strong><p>La versión {draft.version} quedó en borrador. Promueve ahora el catálogo ya guardado.</p></div><Link className="ui-button ui-button--primary ui-button--md" href="/satrapy/contabilidad/catalogo">Continuar al catálogo</Link></section>;
  if (draft && accounts.length) return <div className="accounting-stack"><section className="accounting-readiness"><span className="accounting-readiness__icon"><Landmark size={22} /></span><div><strong>Confirma las cuentas sugeridas</strong><p>Satrapy propuso coincidencias por nombre; el responsable contable debe confirmarlas.</p></div><Badge tone="warning">Paso 3</Badge></section><section className="accounting-panel"><header><div><h2>Vinculación con auxiliares</h2><p>Solo se muestran cuentas afectables. Puedes corregir cualquier sugerencia.</p></div></header><div className="accounting-control-form">{controlKeys.map((key) => <Field label={controlLabels[key]} key={key}><Select ariaLabel={controlLabels[key]} value={selected[key] ?? ""} onValueChange={(value) => setSelected({ ...selected, [key]: value })} placeholder="Selecciona una cuenta" options={accounts.filter((item) => item.accepts_posting).map((account) => ({ value: account.id, label: `${account.code} · ${account.name}` }))} /></Field>)}</div><Field label="Motivo de aprobación" hint="Se registra únicamente al aprobar"><Input value={approvalReason} onChange={(event) => setApprovalReason(event.target.value)} placeholder="Ej. Validado con Contabilidad" /></Field><footer><Button variant="primary" loading={disabled} disabled={disabled || !approvalReason.trim() || !controlKeys.every((key) => selected[key])} onClick={() => void onRun({ action: "complete_config", configId: draft.id, controlAccounts: selected, approvalReason }, "Configuración aprobada")}>Aprobar configuración</Button></footer></section></div>;
  if (!source) return <ManualAccountingSetup companyId={companyId} accounts={accounts} responsibles={data.responsibles} disabled={disabled} canConfigure={canConfigure} onRun={onRun}/>;
  const detectedChanged = baseCurrency !== (source.currency_code ?? "") || cutoff !== (source.cutoff_date ?? "") || format !== (catalogBatch?.catalog_structure.format ?? "");
  const complete = baseCurrency.length === 3 && Boolean(cutoff && format) && Object.values(tax).every(Boolean) && Object.values(responsible).every(Boolean) && (!detectedChanged || Boolean(correctionReason.trim()));
  const responsibleOptions=data.responsibles.map((item)=>({value:item.id,label:item.name}));
  return <div className="accounting-settings-layout"><aside className="accounting-guide"><span><Settings2 size={20} /></span><h2>Ruta de apertura</h2><p>Los datos del archivo se detectan primero; tú confirmas decisiones, no vuelves a capturarlos.</p><ol><li className="is-active"><b>1</b><span><strong>Revisar detección</strong><small>Fecha, moneda y estructura</small></span></li><li><b>2</b><span><strong>Promover catálogo</strong><small>Una sola transacción</small></span></li><li><b>3</b><span><strong>Confirmar controles</strong><small>Y aprobar</small></span></li></ol></aside><div className="accounting-settings-form">
    <section className="accounting-panel"><header><div><h2>Detectado en los archivos</h2><p>La fecha es el último día incluido en la balanza; no es una declaración fiscal.</p></div><Badge tone={source.metadata_issues.length ? "warning" : "success"}>{source.metadata_issues.length ? "Revisar" : "Detectado"}</Badge></header><div className="accounting-form-grid"><Field label="Moneda base" hint={evidenceLabel(source,"currency")}><Input maxLength={3} value={baseCurrency} onChange={(event) => setBaseCurrency(event.target.value.toUpperCase().replace(/[^A-Z]/g, ""))} placeholder="MXN" /></Field><Field label="Fecha de corte" hint={evidenceLabel(source,"cutoffDate")}><Input type="date" value={cutoff} onChange={(event) => setCutoff(event.target.value)} /></Field><Field label="Estructura del catálogo" hint={catalogBatch ? evidenceLabel(catalogBatch,"catalogStructure") : "Falta subir el catálogo"}><Input value={format} onChange={(event) => setFormat(event.target.value)} placeholder="Ej. 4 o 4-3-3" /></Field></div>{detectedChanged && <Field label="Motivo de corrección" hint="Obligatorio porque cambiaste o completaste un dato detectado"><Input value={correctionReason} onChange={(event)=>setCorrectionReason(event.target.value)} placeholder="Explica qué se corrigió" /></Field>}</section>
    <section className="accounting-panel"><header><div><h2>Tratamiento fiscal guiado</h2><p>Opciones explícitas para distinguir IVA y retenciones; valida la selección con Contabilidad.</p></div></header><div className="accounting-form-grid is-two"><TaxSelect label="IVA pendiente" value={tax.vat_pending} onChange={(value)=>setTax({...tax,vat_pending:value})} options={[{value:"effective_cash_flow",label:"Pendiente hasta cobro o pago"}]} /><TaxSelect label="IVA cobrado" value={tax.vat_collected} onChange={(value)=>setTax({...tax,vat_collected:value})} options={[{value:"on_collection",label:"Reconocer al cobro efectivo"}]} /><TaxSelect label="IVA pagado" value={tax.vat_paid} onChange={(value)=>setTax({...tax,vat_paid:value})} options={[{value:"on_payment",label:"Reconocer al pago efectivo"}]} /><TaxSelect label="Retenciones" value={tax.withholdings} onChange={(value)=>setTax({...tax,withholdings:value})} options={[{value:"separate_by_tax",label:"Separar por tipo de impuesto"}]} /></div></section>
    <section className="accounting-panel"><header><div><h2>Responsables</h2><p>Selecciona usuarios con acceso vigente; no se aceptan nombres libres.</p></div></header><div className="accounting-form-grid">{([['adjustments','Ajustes'],['close','Cierre'],['reopen','Reapertura']] as const).map(([key,label])=><Field label={label} key={key}><Select ariaLabel={label} value={responsible[key]} onValueChange={(value)=>setResponsible({...responsible,[key]:value})} placeholder="Selecciona responsable" options={responsibleOptions}/></Field>)}</div><footer><span>{complete ? "Listo para guardar el borrador." : "Revisa los campos pendientes."}</span><Button variant="primary" loading={disabled} disabled={disabled || !complete} onClick={() => void onRun({ action: "save_config_draft", companyId, batchId: source.id, baseCurrency, cutoffDate: cutoff, catalogStructure: {format,segments:format.split("-").map(Number)}, taxTreatment: tax, responsibilities: responsible, correctionReason }, "Detección confirmada")}>Confirmar y continuar</Button></footer></section>
  </div></div>;

  function dataBatch(type: Batch["import_type"]){return data.batches.find((item)=>item.import_type===type && item.status!=="promoted")??data.batches.find((item)=>item.import_type===type);}
}

function ManualAccountingSetup({companyId,accounts,responsibles,disabled,canConfigure,onRun}:{companyId:string;accounts:Account[];responsibles:Responsible[];disabled:boolean;canConfigure:boolean;onRun:(body:Record<string,unknown>,success:string)=>Promise<void>}){
  const first=responsibles[0]?.id??"";const [baseCurrency,setBaseCurrency]=useState("MXN");const [cutoff,setCutoff]=useState(new Date().toISOString().slice(0,10));const [format,setFormat]=useState("4-3-3");const [reason,setReason]=useState("");
  const [responsibility,setResponsibility]=useState<Record<string,string>>({adjustments:first,close:first,reopen:first});const suggested=Object.fromEntries(controlKeys.map(key=>[key,suggestControlAccount(key,accounts)?.id??""]));const [selected,setSelected]=useState<Record<string,string>>(suggested);
  const accountOptions=accounts.filter(item=>item.accepts_posting&&item.is_active).map(item=>({value:item.id,label:`${item.code} · ${item.name}`}));const responsibleOptions=responsibles.map(item=>({value:item.id,label:item.name}));const complete=baseCurrency.length===3&&Boolean(cutoff&&format&&reason.trim())&&controlKeys.every(key=>selected[key])&&Object.values(responsibility).every(Boolean);
  if(!accounts.length)return <div className="accounting-stack"><section className="accounting-readiness"><BookOpen size={22}/><div><strong>Empieza por el catálogo contable</strong><p>Una empresa nueva puede crear pocas cuentas manualmente. Para un catálogo extenso, usa importación.</p></div><Link className="ui-button ui-button--primary ui-button--md" href="/satrapy/contabilidad/catalogo">Crear cuentas</Link></section><section className="accounting-migration-callout"><UploadCloud size={22}/><div><strong>¿Ya tienes un catálogo?</strong><p>La importación masiva sigue disponible y alimenta las mismas cuentas canónicas.</p></div><Link className="ui-button ui-button--secondary ui-button--md" href="/satrapy/configuracion/importaciones">Importar catálogo</Link></section></div>;
  return <div className="accounting-stack"><section className="accounting-readiness"><Settings2 size={22}/><div><strong>Arranque manual con saldo cero</strong><p>No crea una balanza ficticia. Configura la operación nueva; una apertura histórica puede importarse después.</p></div><Badge tone="warning">Sin archivos</Badge></section><section className="accounting-panel"><header><div><h2>Base contable</h2><p>Declara la moneda, fecha de inicio y estructura del catálogo.</p></div></header><div className="accounting-form-grid"><Field label="Moneda base"><Input maxLength={3} value={baseCurrency} onChange={event=>setBaseCurrency(event.target.value.toUpperCase().replace(/[^A-Z]/g,""))}/></Field><Field label="Fecha de inicio"><Input type="date" value={cutoff} onChange={event=>setCutoff(event.target.value)}/></Field><Field label="Estructura"><Input value={format} onChange={event=>setFormat(event.target.value)} placeholder="Ej. 4-3-3"/></Field></div></section><section className="accounting-panel"><header><div><h2>Cuentas de control</h2><p>Confirma las nueve cuentas afectables que conectan auxiliares y contabilidad.</p></div><Badge>{controlKeys.length}</Badge></header><div className="accounting-control-form">{controlKeys.map(key=><Field label={controlLabels[key]} key={key}><Select ariaLabel={controlLabels[key]} value={selected[key]??""} onValueChange={value=>setSelected({...selected,[key]:value})} placeholder="Selecciona una cuenta" options={accountOptions}/></Field>)}</div></section><section className="accounting-panel"><header><div><h2>Responsables y aprobación</h2><p>Se registran usuarios vigentes y el motivo de la configuración inicial.</p></div></header><div className="accounting-form-grid">{([['adjustments','Ajustes'],['close','Cierre'],['reopen','Reapertura']] as const).map(([key,label])=><Field label={label} key={key}><Select ariaLabel={label} value={responsibility[key]} onValueChange={value=>setResponsibility({...responsibility,[key]:value})} options={responsibleOptions}/></Field>)}</div><Field label="Motivo"><Input value={reason} onChange={event=>setReason(event.target.value)} placeholder="Ej. Inicio de operaciones sin saldos históricos"/></Field><footer><span>La aprobación crea la versión 1; cualquier cambio posterior será una nueva versión.</span><Button variant="primary" loading={disabled} disabled={disabled||!canConfigure||!complete} onClick={()=>void onRun({action:"bootstrap_manual_config",companyId,baseCurrency,cutoffDate:cutoff,catalogStructure:{format,segments:format.split("-").map(Number)},taxTreatment:{vat_pending:"effective_cash_flow",vat_collected:"on_collection",vat_paid:"on_payment",withholdings:"separate_by_tax"},responsibilities:responsibility,controlAccounts:selected,reason,clientRequestId:crypto.randomUUID()},"Configuración contable iniciada")}>Aprobar configuración inicial</Button></footer></section></div>;
}

function AccountingRevisionForm({draft,approved,accounts,controls,responsibles,disabled,canConfigure,onRun}:{draft:Config;approved:Config;accounts:Account[];controls:Control[];responsibles:Responsible[];disabled:boolean;canConfigure:boolean;onRun:(body:Record<string,unknown>,success:string)=>Promise<void>}){
  const [baseCurrency,setBaseCurrency]=useState(draft.base_currency);const [cutoff,setCutoff]=useState(draft.cutoff_date);const [format,setFormat]=useState(draft.catalog_structure.format??"");
  const [tax,setTax]=useState<Record<string,string>>(draft.tax_treatment);const [responsibility,setResponsibility]=useState<Record<string,string>>(draft.responsibilities);const [reason,setReason]=useState(draft.change_reason);
  const saved=Object.fromEntries(controls.filter((item)=>item.config_version_id===draft.id).map((item)=>[item.control_key,item.account_id]));const [selected,setSelected]=useState<Record<string,string>>(saved);
  const accountOptions=accounts.filter((item)=>item.accepts_posting&&item.is_active).map((account)=>({value:account.id,label:`${account.code} · ${account.name}`}));const responsibleOptions=responsibles.map((item)=>({value:item.id,label:item.name}));
  const complete=baseCurrency.length===3&&Boolean(cutoff&&format&&reason.trim())&&Object.values(tax).every(Boolean)&&['adjustments','close','reopen'].every((key)=>responsibility[key])&&controlKeys.every((key)=>selected[key]);
  const submit=(approve:boolean)=>onRun({action:"save_config_revision",configId:draft.id,baseCurrency,cutoffDate:cutoff,catalogStructure:{format,segments:format.split("-").map(Number)},taxTreatment:tax,responsibilities:responsibility,controlAccounts:selected,reason,expectedUpdatedAt:draft.updated_at,clientRequestId:crypto.randomUUID(),approve},approve?"Nueva configuración aprobada":"Borrador guardado");
  return <div className="accounting-stack"><section className="accounting-readiness"><span className="accounting-readiness__icon"><Settings2 size={22}/></span><div><strong>Versión {draft.version} en edición</strong><p>La versión {approved.version} continúa vigente. Los cambios sólo entran en operación después de aprobar.</p></div><Badge tone="warning">Borrador</Badge></section>
    <section className="accounting-panel"><header><div><h2>Base y alcance</h2><p>Revisa la versión completa; no sólo las cuentas de control.</p></div></header><div className="accounting-form-grid"><Field label="Moneda base"><Input maxLength={3} value={baseCurrency} onChange={(event)=>setBaseCurrency(event.target.value.toUpperCase().replace(/[^A-Z]/g,""))}/></Field><Field label="Fecha de corte"><Input type="date" value={cutoff} onChange={(event)=>setCutoff(event.target.value)}/></Field><Field label="Estructura del catálogo"><Input value={format} onChange={(event)=>setFormat(event.target.value)} placeholder="Ej. 4-3-3"/></Field></div></section>
    <section className="accounting-panel"><header><div><h2>Tratamiento fiscal</h2><p>Las políticas vigentes se copian como punto de partida y permanecen explícitas.</p></div></header><div className="accounting-form-grid is-two"><TaxSelect label="IVA pendiente" value={tax.vat_pending??""} onChange={(value)=>setTax({...tax,vat_pending:value})} options={[{value:"effective_cash_flow",label:"Pendiente hasta cobro o pago"}]}/><TaxSelect label="IVA cobrado" value={tax.vat_collected??""} onChange={(value)=>setTax({...tax,vat_collected:value})} options={[{value:"on_collection",label:"Reconocer al cobro efectivo"}]}/><TaxSelect label="IVA pagado" value={tax.vat_paid??""} onChange={(value)=>setTax({...tax,vat_paid:value})} options={[{value:"on_payment",label:"Reconocer al pago efectivo"}]}/><TaxSelect label="Retenciones" value={tax.withholdings??""} onChange={(value)=>setTax({...tax,withholdings:value})} options={[{value:"separate_by_tax",label:"Separar por tipo de impuesto"}]}/></div></section>
    <section className="accounting-panel"><header><div><h2>Responsables</h2><p>La asignación usa únicamente usuarios con acceso vigente.</p></div></header><div className="accounting-form-grid">{([['adjustments','Ajustes'],['close','Cierre'],['reopen','Reapertura']] as const).map(([key,label])=><Field label={label} key={key}><Select ariaLabel={label} value={responsibility[key]??""} onValueChange={(value)=>setResponsibility({...responsibility,[key]:value})} placeholder="Selecciona responsable" options={responsibleOptions}/></Field>)}</div></section>
    <section className="accounting-panel"><header><div><h2>Cuentas de control</h2><p>Confirma las nueve vinculaciones con los auxiliares operativos.</p></div><Badge>{controlKeys.length}</Badge></header><div className="accounting-control-form">{controlKeys.map((key)=><Field label={controlLabels[key]} key={key}><Select ariaLabel={controlLabels[key]} value={selected[key]??""} onValueChange={(value)=>setSelected({...selected,[key]:value})} placeholder="Selecciona una cuenta" options={accountOptions}/></Field>)}</div><Field label="Motivo de la versión" hint="Obligatorio para guardar o aprobar"><Input value={reason} onChange={(event)=>setReason(event.target.value)} placeholder="Describe por qué cambia la configuración"/></Field><footer><span>{canConfigure?"Guardar conserva el borrador; aprobar sustituye la versión vigente.":"Tu rol sólo puede consultar esta versión."}</span>{canConfigure&&<><Button variant="secondary" loading={disabled} disabled={disabled||!complete} onClick={()=>void submit(false)}>Guardar borrador</Button><Button variant="primary" loading={disabled} disabled={disabled||!complete} onClick={()=>void submit(true)}>Aprobar nueva versión</Button></>}</footer></section>
  </div>;
}

function TaxSelect({label,value,onChange,options}:{label:string;value:string;onChange:(value:string)=>void;options:Array<{value:string;label:string}>}){return <Field label={label}><Select ariaLabel={label} value={value} onValueChange={onChange} options={options}/></Field>;}
function evidenceLabel(batch:Batch,key:string){const evidence=batch.detection_evidence[key]?.evidence?.[0];return evidence?`Detectado en ${evidence.sheet}, celda ${evidence.cell}`:"No se encontró evidencia; confirma el dato";}
function suggestControlAccount(key:string,accounts:Account[]){const terms:Record<string,string[]>={accounts_receivable:["cuentasporcobrar","clientes"],accounts_payable:["cuentasporpagar","proveedores"],inventory:["inventario","almacen"],cash:["caja"],banks:["banco"],vat_pending:["ivapendiente","ivaacreditable"],vat_collected:["ivacobrado","ivatrasladado"],vat_paid:["ivapagado"],withholdings:["retencion"]};return accounts.find((account)=>terms[key]?.some((term)=>normalizedAccount(account.name).includes(term)));}
function suggestEventAccount(key:string,accounts:Account[]){const terms:Record<string,string[]>={sales_revenue:["ventas","ingresos"],sales_discounts:["descuent"],cost_of_goods_sold:["costodeventa","costoventa"],goods_received_not_invoiced:["recibid","nofactur"],purchase_variance:["variacion","diferenciacompra"],supplier_expense:["gasto","servicio"],cash_opening_offset:["fondodeapertura","fondodecaja","aperturacaja"],cash_close_offset:["retirodecaja","cierrecaja"],cash_movement_offset:["contrapartidademovimientosdecaja","movimientocaja","contrapartidacaja"],cash_over_short:["sobrante","faltante"],supplier_credit_note_offset:["notasdecredito","notadecredito","bonificacioncompra"],inventory_adjustment:["ajustesdeinventario","ajusteinventario"]};return accounts.find((account)=>account.accepts_posting&&terms[key]?.some((term)=>normalizedAccount(account.name).includes(term)));}
function normalizedAccount(value:string){return value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zA-Z0-9]/g,"").toLowerCase();}
function costMethodLabel(value:string){return value==="replacement_cost"?"Costo de reposición":value==="average_cost"?"Costo promedio":value==="standard_cost"?"Costo estándar":value;}
function eventTypeLabel(value:string){const labels:Record<string,string>={sale_confirmed:"Venta confirmada",sale_cancelled:"Venta cancelada",receivable_payment_confirmed:"Cobro confirmado",receivable_payment_reversed:"Cobro revertido",cash_opened:"Apertura de caja",cash_movement_recorded:"Movimiento de caja",cash_movement_reversed:"Movimiento revertido",cash_closed:"Cierre de caja",purchase_receipt_confirmed:"Recepción confirmada",purchase_receipt_reversed:"Recepción revertida",inventory_adjustment_posted:"Ajuste de inventario",inventory_adjustment_reversed:"Ajuste revertido",supplier_invoice_confirmed:"Factura de proveedor",supplier_invoice_reversed:"Factura revertida",supplier_credit_note_confirmed:"Nota de crédito",supplier_credit_note_reversed:"Nota de crédito revertida",supplier_payment_confirmed:"Pago a proveedor",supplier_payment_reversed:"Pago revertido"};return labels[value]??value;}
function sourceTypeLabel(value:string){const labels:Record<string,string>={sale:"Venta",receivable_payment:"Cobro",cash_session:"Caja",cash_movement:"Movimiento de caja",purchase_receipt:"Recepción",inventory_count:"Conteo físico",supplier_invoice:"Documento de proveedor",supplier_payment:"Pago a proveedor"};return labels[value]??value;}
function manualTypeLabel(value:string){return value==="reclassification"?"Reclasificación":value==="correction"?"Corrección":"Ajuste de cierre";}
function manualStatusLabel(value:string){return value==="submitted"?"Por aprobar":value==="approved"?"Aprobado":value==="rejected"?"Rechazado":"Revertido";}
function closeStatusLabel(value:CloseRun["status"]){return value==="prepared"?"Preparado":value==="approved"?"Aprobado":value==="closed"?"Cerrado":"Reabierto";}
function closeCheckLabel(value:string){if(value.startsWith("control_"))return controlLabels[value.slice(8)]??"Auxiliar sin conciliar";const labels:Record<string,string>={journal_balanced:"Debe y haber",pending_events:"Eventos pendientes",draft_journals:"Pólizas en borrador",undecided_adjustments:"Ajustes sin decisión",bank_pending_reconciliation:"Conciliación bancaria pendiente"};return labels[value]??value;}
function formatReportValue(key:string,value:unknown){if(value===null||value===undefined)return "—";if(isAmountKey(key))return money(Number(value));if(key.endsWith("_date"))return formatDate(String(value));if(key==="account_type")return accountTypeLabel(String(value));if(key==="normal_balance")return value==="debit"?"Deudora":"Acreedora";if(key==="control_key")return controlLabels[String(value)]??String(value);return String(value);}

function formatDate(value: string | null) { if (!value) return "—"; const [year, month, day] = value.slice(0, 10).split("-"); return `${day}/${month}/${year}`; }
function money(value: number) { return Number(value).toLocaleString("es-MX", { style: "currency", currency: "MXN", minimumFractionDigits: 2 }); }
function accountTypeLabel(value: string) { return value === "asset" ? "Activo" : value === "liability" ? "Pasivo" : value === "equity" ? "Capital" : value === "revenue" ? "Ingreso" : value === "expense" ? "Gasto" : value; }
